// Who is working with the records on this computer, for what they confirm
// or move: their name in git, as on their commits. Without one, "a team
// member".
import { run } from "@software-factory/core";
const SOMEONE = "a team member";
const known = new Map();
export async function whoIs(project) {
    const kept = known.get(project);
    if (kept)
        return kept;
    const name = await run("git", ["config", "user.name"], { cwd: project })
        .then((out) => out.trim())
        .catch(() => "");
    const who = name && name !== "kobold" ? name : SOMEONE;
    known.set(project, who);
    return who;
}
